use crate :: { Context , ModelId , Transformer } ; use insta :: assert_yaml_snapshot ; use serde :: Serialize ; use super :: * ; use crate :: { ContextMessage , ReasoningConfig , ReasoningFull , Role , TextMessage } ; # [doc = " A transformer that preserves reasoning only for the contiguous tail of"] # [doc = " assistant messages that were produced by the current model, stripping"] # [doc = " reasoning from everything before the first model mismatch (going backwards)."] # [doc = ""] # [doc = " # Behaviour"] # [doc = ""] # [doc = " Walk backwards through the assistant messages. As long as each message's"] # [doc = " model matches `model_id`, its reasoning is kept. The moment a message with"] # [doc = " a different model is encountered that index becomes the *cutoff*: reasoning"] # [doc = " is stripped from that message and every assistant message before it,"] # [doc = " regardless of which model produced them."] # [doc = ""] # [doc = " For example, given the assistant-message sequence `[1 1 1 1 2 1 3 1 2 2 2]`"] # [doc = " with current model `2`:"] # [doc = " - Tail `[2 2 2]` is preserved."] # [doc = " - Everything at or before the `1` that precedes the tail is stripped,"] # [doc = "   including the earlier `2` that appears before the model break."] # [doc = ""] # [doc = " When every assistant message was produced by the current model the"] # [doc = " transformer is a no-op.  When there are no assistant messages it is also a"] # [doc = " no-op."] # [doc = ""] # [doc = " NOTE: `context.reasoning` (the config) is never removed so the new request"] # [doc = " can still enable reasoning on the current turn."] pub struct ReasoningNormalizer { model_id : ModelId , }